# Generator for wars_g14.json (1971 to 2001 conflicts). Edit data here, then run: python3 g14_gen.py
import json, os

H = os.path.dirname(os.path.abspath(__file__))

def T(side, *polities): return {"side": side, "polities": list(polities)}
def F(label, *pts): return {"path": [list(p) for p in pts], "label": label}
def M(side, commander, label, *pts): return {"side": side, "commander": commander, "label": label, "path": [list(p) for p in pts]}
def E(name, kind, lon, lat, year, winner, text): return {"name": name, "kind": kind, "lon": lon, "lat": lat, "year": year, "winner": winner, "text": text}
def S(year, label, title, text, territories, fronts, moves, events):
    return {"year": year, "label": label, "title": title, "text": text, "territories": territories,
            "fronts": fronts, "moves": moves, "events": events}

